def compute_order_amount(on_hand_inventory, pipeline_orders):
    mu = 109.3935545015008  # OPT_PARAM: {"initial": 109.3935545015008, "min": 80, "max": 130, "type": "float"}
    lead_cover = 6.027254047776609  # OPT_PARAM: {"initial": 6.027254047776609, "min": 6, "max": 9, "type": "float"}
    safety_stock = 29.525263752467037  # OPT_PARAM: {"initial": 29.525263752467037, "min": 0, "max": 100, "type": "float"}
    max_order = 95.99525643425011  # OPT_PARAM: {"initial": 95.99525643425011, "min": 90, "max": 200, "type": "float"}
    ip = on_hand_inventory + sum(pipeline_orders)
    target = mu * lead_cover + safety_stock
    uncapped = max(0.0, target - ip)
    order_amount = min(uncapped, max_order)
    return order_amount
